package android.widget;
public class NumberPicker extends LinearLayout { public NumberPicker(android.content.Context c) { super(c); } public NumberPicker(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public NumberPicker(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public NumberPicker(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } private int min,max,value; public void setMinValue(int v) { min=v; } public int getMinValue() { return min; } public void setMaxValue(int v) { max=v; } public int getMaxValue() { return max; } public void setValue(int v) { value=Math.max(min,Math.min(max,v)); } public int getValue() { return value; } }
